content.text:
# PR new hunks — what changed since the last review concluded

Last reviewed head: e0bac8af69266f405cd8432e44216d213094d085
Current head: 83e1225627c7b06c233cefb77f839b7ba340300c

These hunks are the re-review scope, together with their interaction
neighborhood (direct callers/callees of changed symbols). Every line
NOT shown here is frozen: a finding on an unchanged line must show that
these hunks make the problem worse (the interaction test) — otherwise
it is advisory digest only, never a review thread.

--- diff ---

diff --git a/js/common/reviewPoolInJob.js b/js/common/reviewPoolInJob.js
index 3608a997a..544a3c2c9 100644
--- a/js/common/reviewPoolInJob.js
+++ b/js/common/reviewPoolInJob.js
@@ -38,7 +38,7 @@ var reviewVerdicts = require('./reviewVerdicts.js');
 var RUN_AGENT_REL = 'agents/scripts/run-agent.sh';
 var SAFE_IDENTIFIER_RE = /^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/;
 var DEFAULT_SPECIALIST_TIMEOUT_SECONDS = 900;
-var DEFAULT_ROUND_BUDGET_SECONDS = 180;
+var DEFAULT_ROUND_BUDGET_SECONDS = 1800; // 30 minutes — the outer batch cap must EXCEED the per-specialist 900s cap (the review finding: 180 made the units bug — 3 minutes killed the batch before any specialist could finish)
 var CANDIDATES_FILE_PREFIX = 'pr_review_candidates-';
 var COVERAGE_FILE_PREFIX = 'pr_review_coverage-';

@@ -135,6 +135,19 @@ function coverageSection(roundCtx, prev) {
  * contract paths are passed as REPO PATHS (the child reads them itself —
  * the content stays single-sourced in the pack).
  */
+/**
+ * The diff file for the round: the machine names it per round (the hunks
+ * delta on re-reviews; the standard full PR diff on first rounds — a first
+ * round never materializes pr_new_hunks.txt, the review BLOCKING).
+ */
+function diffFileOf(roundCtx) {
+    if (roundCtx && roundCtx.diffFile) return roundCtx.diffFile;
+    var ticket = (roundCtx && roundCtx.ticketKey) || '';
+    return roundCtx && roundCtx.hasNewHunks
+        ? 'input/' + ticket + '/pr_new_hunks.txt'
+        : 'input/' + ticket + '/pr_diff.txt';
+}
+
 /**
  * The read-first + round-context block: the reference-pack line renders
  * only when the skill carries one, and the scope line flips on new hunks.
@@ -147,7 +160,7 @@ function specialistContextLines(skill, roundCtx) {
             : '') +
         '- Candidates contract: `agents/instructions/pr_review/base/output_rules.md`',
         '  (the candidates-only output section — your ONLY output)',
-        '- Diff under review: `input/' + (roundCtx.ticketKey || '') + '/pr_new_hunks.txt` —',
+        '- Diff under review: `' + diffFileOf(roundCtx) + '` —',
         '  AUTHORITATIVE and pre-verified by the machine: review its content as',
         '  given (the repo checkout provides the surrounding files)',
         '',
@@ -436,15 +449,19 @@ function readSpecialistOutcomes(io, pool, roundCtx) {
         } else {
             out.unavailable.push(name);
             out.results.push({ reviewer: name, ok: false, reason: outcome.reason });
-        }
-        var cov = readCoverage(io, name);
-        if (cov && (cov.covered.length > 0 || cov.pending.length > 0)) {
-            out.coverageNotes.push({
-                reviewer: name,
-                text: 'no candidates — coverage memory persisted (covered ' +
-                    cov.covered.length + ', pending ' + cov.pending.length +
-                    '); the next pass continues it'
-            });
+            // The continuation note ONLY for a specialist that did NOT
+            // deliver candidates (the review finding: the block previously
+            // ran for every specialist — a completed one would get a lying
+            // "no candidates" note while its candidates were accepted).
+            var cov = readCoverage(io, name);
+            if (cov && (cov.covered.length > 0 || cov.pending.length > 0)) {
+                out.coverageNotes.push({
+                    reviewer: name,
+                    text: 'no candidates — coverage memory persisted (covered ' +
+                        cov.covered.length + ', pending ' + cov.pending.length +
+                        '); the next pass continues it'
+                });
+            }
         }
     }
     return out;
diff --git a/js/common/reviewPoolLegSetup.js b/js/common/reviewPoolLegSetup.js
index 218e8ff8f..1d9ca4c33 100644
--- a/js/common/reviewPoolLegSetup.js
+++ b/js/common/reviewPoolLegSetup.js
@@ -91,7 +91,16 @@ function roundContextOf(deps, ctx, prDetails, comments) {
         ticketKey: ctx.ticketKey,
         headSha: prDetails.head && prDetails.head.sha,
         hasNewHunks: hunks.hasNewHunks,
-        newHunkPaths: hunks.newHunkPaths
+        newHunkPaths: hunks.newHunkPaths,
+        // The diff file the specialist prompt points at MUST exist on every
+        // round (the review finding: the prompt rendered the hunks path
+        // unconditionally, but pr_new_hunks.txt is materialized only on
+        // re-reviews — a first round (no verdict record) never writes it,
+        // leaving the specialist a file that is not there). First rounds
+        // review the standard full PR diff instead.
+        diffFile: hunks.hasNewHunks
+            ? 'input/' + (ctx.ticketKey || '') + '/pr_new_hunks.txt'
+            : 'input/' + (ctx.ticketKey || '') + '/pr_diff.txt'
     };
 }

